def conjugate(verb):
    suffixes = {
        'ar': ['o', 'as', 'a', 'amos', 'ais', 'an'],
        'er': ['o', 'es', 'e', 'emos', 'eis', 'en'],
        'ir': ['o', 'es', 'e', 'imos', 'is', 'en']
    }
    stem = verb[:-2]
    conjugations = [stem + suffix for suffix in suffixes[verb[-2:]]]
    return {verb: conjugations}
